package com.nexamart.backend.api;import com.nexamart.backend.api.ApiModels.*;import com.nexamart.backend.service.CustomerService;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/v1/customer")public class CustomerController{final CustomerService s;public CustomerController(CustomerService s){this.s=s;}@PostMapping("/orders")OrderResponse create(@Valid @RequestBody CreateOrderRequest r){return s.create(r);}@GetMapping("/orders")PageResponse<OrderResponse> history(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize){return s.history(page,pageSize);}@GetMapping("/orders/{id}")OrderResponse detail(@PathVariable Long id){return s.detail(id);}}
